"""Gemma-2 final-layer tanh logit soft-capping fused with log-softmax."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'gemma2_softcapped_log_softmax',
    'num_tokens': 1024,
    'vocab_size': 262144,
    'softcap': 30.0,
}


def create_inputs(dtype=jnp.bfloat16):
    key = jax.random.key(0)
    logits = jax.random.normal(
        key, (CONFIG['num_tokens'], CONFIG['vocab_size']), dtype=dtype
    ) * 10.0
    return (logits,)


def workload(logits):
    softcap = CONFIG['softcap']
    x = logits.astype(jnp.float32)
    capped = softcap * jnp.tanh(x / softcap)
    return jax.nn.log_softmax(capped, axis=-1)

"""Gemma-2 style final-layer logit tanh soft-capping fused with log-softmax."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'gemma2_softcapped_log_softmax',
    'batch_size': 2,
    'seq_len': 512,
    'vocab_size': 262144,
    'softcap': 30.0,
}


def create_inputs(dtype=jnp.bfloat16):
    key = jax.random.key(0)
    shape = (CONFIG['batch_size'], CONFIG['seq_len'], CONFIG['vocab_size'])
    logits = jax.random.normal(key, shape, dtype=dtype) * 20.0
    return (logits,)


def workload(logits):
    cap = CONFIG['softcap']
    x = logits.astype(jnp.float32)
    capped = cap * jnp.tanh(x / cap)
    return jax.nn.log_softmax(capped, axis=-1)

"""Hinge Loss for binary classification: mean(maximum(0, 1 - predictions * targets))."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': '100_HingeLoss',
    'batch_size': 8192,
    'features': 8192,
    'margin': 1.0,
}

def create_inputs(dtype=jnp.float32):
    k1, k2 = jax.random.split(jax.random.key(0), 2)
    B = CONFIG['batch_size']
    F = CONFIG['features']
    predictions = jax.random.uniform(k1, (B, F), dtype=dtype)
    targets_int = jax.random.randint(k2, (F,), 0, 2)
    targets = (targets_int.astype(dtype) * 2.0) - 1.0
    return (predictions, targets)

def workload(predictions, targets):
    margin = CONFIG['margin']
    return jnp.mean(jnp.maximum(0.0, margin - predictions * targets))

